# First, let's get the first page to know how many pages there are
first_page = list_orders({ month: "2026-03", page: 1 })

# Fetch remaining pages concurrently
remaining_pages = for page in list.range(2, first_page.total_pages + 1) {
    result = list_orders({ month: "2026-03", page })
    return result.items
}

# Combine all items
all_items = fold acc = first_page.items for page in remaining_pages {
    return acc + page
}

# Now get order details and customer details for each order
# First, get all orders in parallel
enriched = for item in all_items {
    order = get_order({ id: item.id })
    # Only proceed if order is completed
    skip if order.status != "completed"
    customer = get_customer({ id: order.customer_id })
    return {
        order_id: item.id,
        amount_cents: order.amount_cents,
        region: customer.region
    }
}

# Now aggregate by region
na_total = fold acc = 0 for row in enriched {
    return acc + (row.amount_cents if row.region == "NA" else 0)
}
eu_total = fold acc = 0 for row in enriched {
    return acc + (row.amount_cents if row.region == "EU" else 0)
}
apac_total = fold acc = 0 for row in enriched {
    return acc + (row.amount_cents if row.region == "APAC" else 0)
}

return { NA: na_total, EU: eu_total, APAC: apac_total }

